uses {IO}
import IO
import String
import List
import Map

let host_of line =
  let rest =
    if String.starts_with? "https://" line then Some (String.slice 8 (String.length line) line)
    else if String.starts_with? "http://" line then Some (String.slice 7 (String.length line) line)
    else None
  match rest with
  | None -> ""
  | Some r ->
    let h = r |> String.split "/" |> List.head! |> String.split "?" |> List.head! |> String.split "#" |> List.head! |> String.split ":" |> List.head!
    String.lower h

let lines = String.lines (IO.read_all! ()) |> List.map String.trim |> List.filter (fn l -> !(String.empty? l))
let hosts = List.map host_of lines
let good = List.filter (fn h -> !(String.empty? h)) hosts
let bad = List.length hosts - List.length good
let ranked = List.tally good |> Map.to_list |> List.sort_by (fn p -> (0 - p.1, p.0))
List.each (fn p -> IO.println "%{p.1} %{p.0}") ranked
if bad > 0 then IO.println "%{bad} invalid" else ()
EOF
