let good = List.filter (fn h -> !(String.empty? h)) hosts
let bad = List.length hosts - List.length good
let ranked = List.sort_by (fn p -> (0 - p.1, p.0)) (Map.to_list (List.tally good))
List.each (fn p -> IO.println "%{p.1} %{p.0}") ranked
if bad > 0 then IO.println "%{bad} invalid" else ()
EOF
