uses {IO}
import IO
import Stream
import List
import Map
import String
import Decode
import Int

let rec_dec = Decode.map2 (fn e m -> (e, m)) (Decode.field "endpoint" Decode.string) (Decode.field "ms" Decode.int)

let pct sorted n p =
  let r = (p * n + 99) / 100;
  match List.get (r - 1) sorted with
  | Some v -> v
  | None -> 0

let step acc line =
  let {groups, skipped} = acc;
  if String.empty? (String.trim line) then acc
  else
    match Decode.run rec_dec line with
    | Ok (e, m) ->
      if m >= 0 then {groups = Map.update e [] (fn xs -> m :: xs) groups, skipped}
      else {groups, skipped = skipped + 1}
    | Error _ -> {groups, skipped = skipped + 1}

let res = IO.stdin_lines () |> Stream.fold_left step {groups = Map.empty, skipped = 0}
List.each (fn k ->
  let sorted = List.sort (Map.get! k res.groups);
  let n = List.length sorted;
  IO.println "%{k} count=%{n} p50=%{pct sorted n 50} p95=%{pct sorted n 95}") (List.sort (Map.keys res.groups))
if res.skipped > 0 then IO.println "skipped %{res.skipped}" else ()
EOF
